-- Migração dos Welcome Packs por serviço
-- Gerada localmente; aplicar no projeto Supabase correto após confirmação explícita.

alter table public.service_documents add column if not exists content jsonb not null default '{}'::jsonb;

alter table public.service_documents drop constraint if exists service_documents_service_type_check;

alter table public.service_documents add constraint service_documents_service_type_check check (service_type = any (array['branding'::text, 'identidade-visual'::text, 'social-media'::text, 'design-publicitario'::text, 'design-eventos'::text, 'web-design'::text, 'materiais-graficos'::text]));

drop policy if exists "leitura pública dos Welcome Packs" on public.service_documents;

create policy "leitura pública dos Welcome Packs" on public.service_documents for select to anon, authenticated using (true);

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('branding', 'Branding', 'Obrigado por confiares o posicionamento da tua marca a este processo. Vamos transformar a essência do negócio numa presença clara, reconhecível e consistente.', ARRAY['Contexto', 'Materiais', 'Decisões', 'Feedback']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Imersão', 'Direção', 'Sistema', 'Entrega']::text[], '{"serviceType":"branding","title":"Branding","welcomeMessage":"Obrigado por confiares o posicionamento da tua marca a este processo. Vamos transformar a essência do negócio numa presença clara, reconhecível e consistente.","includes":["Contexto","Materiais","Decisões","Feedback"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"UMA MARCA FORTE COMEÇA COM UMA DIREÇÃO CLARA."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares o posicionamento da tua marca a este processo. Vamos transformar a essência do negócio numa presença clara, reconhecível e consistente."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Vamos começar por compreender a marca, organizar a sua essência e transformar essa clareza num sistema visual com intenção.","steps":[{"number":"01","title":"Imersão","text":"Leio o briefing e organizo a história, os objetivos e o posicionamento da marca."},{"number":"02","title":"Direção","text":"Traduzo a personalidade do negócio em caminhos visuais possíveis e bem fundamentados."},{"number":"03","title":"Sistema","text":"Desenvolvo os elementos que tornam a marca coerente em diferentes pontos de contacto."},{"number":"04","title":"Entrega","text":"Reúno os materiais finais e explico como usar a nova direção com consistência."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Essência","text":"A marca precisa de dizer algo verdadeiro antes de procurar apenas parecer diferente."},{"number":"02","title":"Coerência","text":"Cada elemento deve fazer parte do mesmo sistema e reforçar a mesma percepção."},{"number":"03","title":"Presença","text":"O resultado deve funcionar tanto num detalhe como numa aplicação completa."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Contexto","text":"História da marca, objetivos, público e referências do negócio."},{"index":"B","title":"Materiais","text":"Logótipo atual, textos, imagens, produtos e outros ficheiros existentes."},{"index":"C","title":"Decisões","text":"Preferências, limites e prioridades que ajudem a escolher a direção certa."},{"index":"D","title":"Feedback","text":"Comentários objetivos reunidos num único momento para cada apresentação."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"A partir daqui, vamos dar forma àquilo que a tua marca quer dizer."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('identidade-visual', 'Identidade Visual', 'Obrigado por confiares a identidade visual do teu projeto a este processo. Vou transformar a tua visão numa linguagem visual simples, coerente e fácil de reconhecer.', ARRAY['Logótipo', 'Referências', 'Conteúdo', 'Feedback']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Revisão', 'Conceito', 'Refinamento', 'Entrega']::text[], '{"serviceType":"identidade-visual","title":"Identidade Visual","welcomeMessage":"Obrigado por confiares a identidade visual do teu projeto a este processo. Vou transformar a tua visão numa linguagem visual simples, coerente e fácil de reconhecer.","includes":["Logótipo","Referências","Conteúdo","Feedback"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"UMA IDENTIDADE CLARA DÁ FORÇA A CADA PONTO DE CONTACTO."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares a identidade visual do teu projeto a este processo. Vou transformar a tua visão numa linguagem visual simples, coerente e fácil de reconhecer."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"A partir das tuas respostas, vamos construir uma direção visual que seja fácil de compreender, aplicar e reconhecer.","steps":[{"number":"01","title":"Revisão","text":"Leio o briefing, organizo prioridades e identifico o que a identidade precisa de comunicar."},{"number":"02","title":"Conceito","text":"Apresento uma direção visual com escolhas explicadas e alinhadas com o projeto."},{"number":"03","title":"Refinamento","text":"Ajusto os elementos essenciais com base no teu feedback e nas decisões aprovadas."},{"number":"04","title":"Entrega","text":"Preparo os ficheiros finais para que possas usar a identidade com segurança."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Clareza","text":"A identidade deve ser compreendida rapidamente por quem entra em contacto com ela."},{"number":"02","title":"Personalidade","text":"As escolhas visuais devem refletir o caráter do projeto e não apenas seguir tendências."},{"number":"03","title":"Aplicação","text":"O sistema deve funcionar em diferentes tamanhos, suportes e situações."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Logótipo","text":"Versões existentes, ficheiros editáveis e aplicações onde a identidade já aparece."},{"index":"B","title":"Referências","text":"Imagens, marcas ou estilos que ajudam a explicar o que sentes que combina contigo."},{"index":"C","title":"Conteúdo","text":"Nome, assinatura, textos, imagens e informações que devam fazer parte do sistema."},{"index":"D","title":"Feedback","text":"Uma resposta clara sobre o que funciona, o que falta e o que deve ser ajustado."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"Agora começa a transformação da tua visão numa identidade que pode crescer contigo."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('social-media', 'Social Media Design', 'Obrigado por confiares a comunicação visual das tuas redes a este processo. Vamos criar uma presença mais consistente, clara e preparada para comunicar com o teu público.', ARRAY['Conteúdos', 'Imagens', 'Prioridades', 'Calendário']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Contexto', 'Direção', 'Conteúdo', 'Entrega']::text[], '{"serviceType":"social-media","title":"Social Media Design","welcomeMessage":"Obrigado por confiares a comunicação visual das tuas redes a este processo. Vamos criar uma presença mais consistente, clara e preparada para comunicar com o teu público.","includes":["Conteúdos","Imagens","Prioridades","Calendário"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"CADA PUBLICAÇÃO É UMA OPORTUNIDADE PARA SER RECONHECIDO."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares a comunicação visual das tuas redes a este processo. Vamos criar uma presença mais consistente, clara e preparada para comunicar com o teu público."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Vamos organizar a mensagem, o ritmo e a aparência das tuas redes para que cada publicação faça parte da mesma presença.","steps":[{"number":"01","title":"Contexto","text":"Analiso o briefing, o público e os objetivos da comunicação nas redes."},{"number":"02","title":"Direção","text":"Defino uma linha visual que possa ser reconhecida sem tornar a comunicação repetitiva."},{"number":"03","title":"Conteúdo","text":"Organizo formatos, textos e referências para orientar a criação das peças."},{"number":"04","title":"Entrega","text":"Preparo os materiais finais de forma simples para publicação e continuidade."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Reconhecimento","text":"As peças devem ser percebidas como parte da mesma marca, mesmo quando o tema muda."},{"number":"02","title":"Ritmo","text":"Uma boa direção cria variedade dentro de um sistema visual fácil de manter."},{"number":"03","title":"Ação","text":"O design deve ajudar a mensagem a ser entendida e a provocar uma resposta."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Conteúdos","text":"Textos, datas, temas, ofertas e informações que precisam de ser comunicados."},{"index":"B","title":"Imagens","text":"Fotografias, produtos, logótipo e referências que possam enriquecer as peças."},{"index":"C","title":"Prioridades","text":"Objetivos da campanha, público principal e ação que queres incentivar."},{"index":"D","title":"Calendário","text":"Disponibilidade para validar conteúdos e manter o projeto a avançar."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"A partir daqui, vamos transformar informação em presença e presença em ligação."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('design-publicitario', 'Design Publicitário & Campanhas', 'Obrigado por confiares esta campanha a este processo. Vamos organizar a mensagem e criar uma peça que capte atenção sem perder clareza.', ARRAY['Mensagem', 'Formato', 'Referências', 'Prazo']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Briefing', 'Mensagem', 'Criação', 'Preparação']::text[], '{"serviceType":"design-publicitario","title":"Design Publicitário & Campanhas","welcomeMessage":"Obrigado por confiares esta campanha a este processo. Vamos organizar a mensagem e criar uma peça que capte atenção sem perder clareza.","includes":["Mensagem","Formato","Referências","Prazo"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"UMA BOA CAMPANHA DIZ O ESSENCIAL NO MOMENTO CERTO."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares esta campanha a este processo. Vamos organizar a mensagem e criar uma peça que capte atenção sem perder clareza."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Começamos por clarificar a mensagem, o público e o objetivo para que o design tenha impacto e direção.","steps":[{"number":"01","title":"Briefing","text":"Reúno a informação principal, o objetivo da campanha e a ação esperada."},{"number":"02","title":"Mensagem","text":"Organizo o conteúdo para que a ideia principal apareça com clareza."},{"number":"03","title":"Criação","text":"Desenvolvo a peça ou conjunto de peças com uma direção visual coerente."},{"number":"04","title":"Preparação","text":"Entrego os ficheiros adequados aos canais e formatos definidos."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Impacto","text":"A primeira leitura deve captar atenção sem obrigar a pessoa a decifrar a mensagem."},{"number":"02","title":"Foco","text":"Cada peça precisa de uma ideia principal e de uma ação compreensível."},{"number":"03","title":"Adequação","text":"O formato e a linguagem devem responder ao público e ao contexto da campanha."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Mensagem","text":"Texto final, oferta, chamada para ação e informação que não pode faltar."},{"index":"B","title":"Formato","text":"Medidas, plataforma, impressão ou aplicação onde a campanha será utilizada."},{"index":"C","title":"Referências","text":"Exemplos, imagens, produtos e materiais que ajudem a construir o caminho."},{"index":"D","title":"Prazo","text":"Data real de publicação ou utilização para organizar a produção."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"Agora vamos transformar a mensagem da campanha numa imagem que pede atenção."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('design-eventos', 'Identidade Visual para Eventos', 'Obrigado por confiares a identidade do teu evento a este processo. Vamos criar uma direção visual que ajude o evento a ser reconhecido antes, durante e depois de acontecer.', ARRAY['Programa', 'Espaço', 'Produção', 'Decisões']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Enquadramento', 'Conceito', 'Aplicações', 'Entrega']::text[], '{"serviceType":"design-eventos","title":"Identidade Visual para Eventos","welcomeMessage":"Obrigado por confiares a identidade do teu evento a este processo. Vamos criar uma direção visual que ajude o evento a ser reconhecido antes, durante e depois de acontecer.","includes":["Programa","Espaço","Produção","Decisões"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"UM EVENTO MEMORÁVEL COMEÇA ANTES DA PRIMEIRA PESSOA CHEGAR."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares a identidade do teu evento a este processo. Vamos criar uma direção visual que ajude o evento a ser reconhecido antes, durante e depois de acontecer."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Vamos organizar a atmosfera, os momentos e os suportes do evento para construir uma experiência visual coerente.","steps":[{"number":"01","title":"Enquadramento","text":"Compreendo o tipo de evento, o público, o ambiente e os momentos mais importantes."},{"number":"02","title":"Conceito","text":"Defino uma ideia visual capaz de orientar todas as aplicações do evento."},{"number":"03","title":"Aplicações","text":"Desenvolvo os materiais necessários para comunicar e acompanhar a experiência."},{"number":"04","title":"Entrega","text":"Organizo os ficheiros finais para produção, divulgação e utilização no local."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Atmosfera","text":"A identidade deve transmitir o sentimento que queres que as pessoas levem do evento."},{"number":"02","title":"Orientação","text":"Cada peça deve ajudar as pessoas a saber onde estão e o que acontece a seguir."},{"number":"03","title":"Memória","text":"Uma direção coerente torna o evento mais fácil de reconhecer e recordar."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Programa","text":"Datas, horários, momentos, convidados e informações que estruturam o evento."},{"index":"B","title":"Espaço","text":"Medidas, plantas, suportes disponíveis e locais onde a identidade será aplicada."},{"index":"C","title":"Produção","text":"Materiais, quantidades, fornecedores e limitações técnicas já conhecidas."},{"index":"D","title":"Decisões","text":"Validações rápidas para que a produção possa avançar sem atrasos."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"Agora começa a construção da atmosfera visual que vai acompanhar o teu evento."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('web-design', 'Web Design', 'Obrigado por confiares a presença digital do teu projeto a este processo. Vamos organizar conteúdo, navegação e imagem para criar uma experiência simples e eficaz.', ARRAY['Conteúdo', 'Referências', 'Funcionalidades', 'Acessos']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Estrutura', 'Direção', 'Interface', 'Preparação']::text[], '{"serviceType":"web-design","title":"Web Design","welcomeMessage":"Obrigado por confiares a presença digital do teu projeto a este processo. Vamos organizar conteúdo, navegação e imagem para criar uma experiência simples e eficaz.","includes":["Conteúdo","Referências","Funcionalidades","Acessos"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"UM BOM WEBSITE TORNA A PRÓXIMA DECISÃO MAIS FÁCIL."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares a presença digital do teu projeto a este processo. Vamos organizar conteúdo, navegação e imagem para criar uma experiência simples e eficaz."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Antes de desenhar ecrãs, vamos compreender o conteúdo, as pessoas e as ações que o website precisa de facilitar.","steps":[{"number":"01","title":"Estrutura","text":"Organizo páginas, conteúdos e prioridades para criar uma navegação compreensível."},{"number":"02","title":"Direção","text":"Defino uma linguagem visual digital alinhada com a marca e com o objetivo do website."},{"number":"03","title":"Interface","text":"Desenvolvo os ecrãs e componentes que dão forma à experiência."},{"number":"04","title":"Preparação","text":"Reúno os materiais finais e os detalhes necessários para a implementação."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Usabilidade","text":"A pessoa deve encontrar o que procura sem esforço ou confusão."},{"number":"02","title":"Hierarquia","text":"O conteúdo importante deve ter prioridade visual e orientar a navegação."},{"number":"03","title":"Confiança","text":"O website deve parecer claro, cuidado e coerente em cada ponto de contacto."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Conteúdo","text":"Textos, páginas, imagens, serviços, contactos e chamadas para ação."},{"index":"B","title":"Referências","text":"Websites, marcas e exemplos de experiências que fazem sentido para o projeto."},{"index":"C","title":"Funcionalidades","text":"Formulários, integrações, pagamentos ou comportamentos necessários."},{"index":"D","title":"Acessos","text":"Domínio, alojamento, ferramentas e pessoas envolvidas na implementação."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"A partir daqui, vamos transformar a informação do projeto numa experiência digital clara."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();

insert into public.service_documents (service_type, title, welcome_message, includes, revisions, delivery_time, payment_method, next_steps, content) values ('materiais-graficos', 'Materiais Gráficos & Impressos', 'Obrigado por confiares estes materiais ao processo. Vamos garantir que cada peça comunica bem e está preparada para o suporte onde será utilizada.', ARRAY['Conteúdo', 'Formato', 'Imagens', 'Produção']::text[], '2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.', 'A confirmar após análise do briefing', '50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.', ARRAY['Inventário', 'Direção', 'Desenvolvimento', 'Artes finais']::text[], '{"serviceType":"materiais-graficos","title":"Materiais Gráficos & Impressos","welcomeMessage":"Obrigado por confiares estes materiais ao processo. Vamos garantir que cada peça comunica bem e está preparada para o suporte onde será utilizada.","includes":["Conteúdo","Formato","Imagens","Produção"],"deliveryTime":"A confirmar após análise do briefing","revisions":"2 rondas de revisão incluídas. Alterações adicionais são cobradas à parte.","paymentMethod":"50% adiantado, 50% na entrega. Pagamento por transferência bancária ou Multicaixa.","page1":{"eyebrow":"WELCOME PACK","slogan":"BONS MATERIAIS TORNAM A MENSAGEM PRESENTE NO MUNDO REAL."},"page2":{"eyebrow":"BOAS-VINDAS","titleLine1":"Obrigado por","titleEmphasis":"confiares no processo.","noteLabel":"NOTA / 01","noteText":"Este documento é um guia breve para o início do nosso trabalho. As respostas completas do briefing ficam reservadas à análise interna do projeto.","intro":"Obrigado por confiares estes materiais ao processo. Vamos garantir que cada peça comunica bem e está preparada para o suporte onde será utilizada."},"page3":{"eyebrow":"A PARTIR DE AGORA","titleLine1":"O que acontece","titleEmphasis":"agora.","intro":"Começamos por compreender a função de cada peça, o público e as condições reais de produção.","steps":[{"number":"01","title":"Inventário","text":"Reúno os materiais, formatos, quantidades e objetivos de cada peça."},{"number":"02","title":"Direção","text":"Escolho uma solução visual coerente com a marca e adequada ao suporte."},{"number":"03","title":"Desenvolvimento","text":"Crio e ajusto as peças com atenção à leitura, escala e preparação técnica."},{"number":"04","title":"Artes finais","text":"Entrego os ficheiros preparados para utilização ou envio à produção."}]},"page4":{"eyebrow":"UMA FORMA DE TRABALHAR","titleLine1":"Clareza antes","titleEmphasis":"da forma.","intro":"O design torna-se mais forte quando existe uma intenção clara por trás de cada escolha. É isso que vamos construir em conjunto.","timeline":["ENTENDER","DEFINIR","DESENVOLVER","ENTREGAR"],"principles":[{"number":"01","title":"Leitura","text":"A informação deve continuar clara no tamanho e distância em que será vista."},{"number":"02","title":"Consistência","text":"As diferentes peças devem parecer parte da mesma comunicação."},{"number":"03","title":"Preparação","text":"O ficheiro final precisa de respeitar as exigências do suporte e da produção."}]},"page5":{"eyebrow":"PARA AVANÇAR COM RITMO","titleLine1":"O que precisamos","titleEmphasis":"de ti.","intro":"Já recebemos o primeiro passo. Ao longo do projeto, estes são os elementos que ajudam a tomar decisões mais rápidas e fiéis à tua realidade.","calloutLabel":"IMPORTANTE","calloutTitle":"Se ainda não tens tudo pronto, não há problema.","calloutText":"Partilha o que já existe. O processo também serve para descobrir o que falta.","needs":[{"index":"A","title":"Conteúdo","text":"Textos finais, contactos, medidas, preços e informações obrigatórias."},{"index":"B","title":"Formato","text":"Dimensões, material, quantidade e local onde cada peça será usada."},{"index":"C","title":"Imagens","text":"Fotografias, logótipo, ilustrações e referências disponíveis."},{"index":"D","title":"Produção","text":"Fornecedor, prazo, especificações técnicas e orçamento conhecido."}]},"page6":{"eyebrow":"PARA MANTER O PROJETO EM MOVIMENTO","titleLine1":"Prazos claros.","titleEmphasis":"Comunicação simples.","intro":"O calendário final será confirmado depois da revisão do briefing e depende da dimensão, urgência e número de etapas do projeto.","contactLabel":"CONTACTO DIRETO","schedule":[{"label":"01 / PRAZO ESTIMADO","title":"A confirmar após análise","dark":true},{"label":"02 / ALTERAÇÕES","title":"Duas rondas incluídas","dark":false},{"label":"03 / PAGAMENTO","title":"Condições combinadas","dark":false},{"label":"04 / APROVAÇÃO","title":"Depois de validar, avançamos","text":"Cada etapa segue para a próxima quando a direção estiver aprovada.","dark":false}],"contactEmail":"pedromuindi5@gmail.com","contactUrl":"www.lucasmuindi.vercel.app"},"page7":{"eyebrowPrefix":"ATÉ JÁ,","closeHeadlineLine1":"Vamos criar algo","closeHeadlineEmphasis":"com sentido.","footerEmail":"pedromuindi5@gmail.com","footerUrl":"www.lucasmuindi.vercel.app","closeText":"Agora vamos transformar a informação do projeto em materiais prontos para circular."},"shared":{"contactEmail":"pedromuindi5@gmail.com","portfolioUrl":"www.lucasmuindi.vercel.app"}}') on conflict (service_type) do update set title = excluded.title, welcome_message = excluded.welcome_message, includes = excluded.includes, revisions = excluded.revisions, delivery_time = excluded.delivery_time, payment_method = excluded.payment_method, next_steps = excluded.next_steps, content = excluded.content, updated_at = now();
